const $=s=>document.querySelector(s);let scanner=null,locked=false;
$("#modeBadge").textContent=PREMIERE_API.configured?"REALTIME ONLINE":"DEMO MODE";
async function stop(){if(scanner?.isScanning)try{await scanner.stop()}catch{}}
async function process(raw){if(locked)return;locked=true;try{const r=await PREMIERE_API.checkIn(raw),t=PREMIERE.tickets.find(x=>x.ticketId===(r.ticket_id||r.ticketId))||r,teacher=t.type==="teacher"||t.ticket_type==="teacher";await stop();const pane=$("#scanResult");pane.className=`scan-result ${r.status} ${teacher&&r.status==="valid"?"teacher":""}`;$("#resultKicker").textContent=teacher&&r.status==="valid"?"SPECIAL ACCESS DETECTED":r.status==="valid"?"TICKET VERIFIED":r.status==="used"?"DUPLICATE SCAN":"ACCESS DENIED";$("#resultTitle").textContent=r.status==="valid"?"ACCESS GRANTED":r.status==="used"?"ALREADY CHECKED IN":"INVALID TICKET";$("#resultName").textContent=t.name||"UNKNOWN PASS";$("#resultMeta").textContent=t.name?`${teacher?"HONORED GUEST":t.role||"GUEST"} · № ${t.number||"—"}`:(r.ticket_id||"Код не знайдено");$("#teacherSecret").hidden=!(teacher&&r.status==="valid");pane.hidden=false}catch(e){locked=false;$("#cameraHelp").textContent=`Не вдалося перевірити квиток: ${e.message}`}}
async function start(){if(!window.Html5Qrcode){$("#cameraHelp").textContent="Модуль камери не завантажився. Скористайтеся демо-кнопками.";return}scanner||=new Html5Qrcode("reader");try{await scanner.start({facingMode:"environment"},{fps:10,qrbox:(w,h)=>({width:Math.min(w,h)*.72,height:Math.min(w,h)*.72})},process,()=>{});$("#startScanner").hidden=true;$("#cameraHelp").textContent="Камера активна · шукаємо QR-код"}catch{$("#cameraHelp").textContent="Камера недоступна. Перевірте дозвіл або використайте демо-тест."}}
PREMIERE.tickets.forEach(t=>{const b=document.createElement("button");b.textContent=`${t.number} · ${t.name}`;b.onclick=()=>process(PREMIERE.qrPayload(t));$("#testTickets").appendChild(b)});$("#startScanner").onclick=start;$("#scanAgain").onclick=async()=>{$("#scanResult").hidden=true;locked=false;await start()};const query=new URLSearchParams(location.search),direct=query.get("t")||query.get("ticket");if(direct)process(location.href);
